package repo

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"testing"
)

// polyglot is a small repository with one manifest per ecosystem, test files of several kinds,
// generated files and an entrypoint layout. Nothing in it is built or executed.
var polyglot = map[string]string{
	"go.mod": `module example.com/shop

go 1.24.0

require (
	github.com/stretchr/testify v1.9.0
	golang.org/x/exp v0.0.0-20240101 // indirect
)
`,
	"cmd/api/main.go":                "package main\n",
	"cmd/worker/main.go":             "package main\n",
	"internal/orders/orders.go":      "package orders\n",
	"internal/orders/orders_test.go": "package orders\n",
	"internal/orders/gen.pb.go":      "package orders\n",
	"internal/orders/header.go":      "// Code generated by stringer. DO NOT EDIT.\n\npackage orders\n",
	"web/package.json":               `{"dependencies": {"express": "^4.18.2"}, "devDependencies": {"jest": "^29.7.0"}}`,
	"web/package-lock.json":          "{}",
	"web/tsconfig.json":              "{}",
	"src/index.ts":                   "export const x = 1;\n",
	"src/index.test.ts":              "test('x', () => {});\n",
	"pom.xml":                        `<project><dependencies><dependency><groupId>org.junit.jupiter</groupId><artifactId>junit-jupiter</artifactId><version>5.10.0</version></dependency></dependencies></project>`,
	"android/build.gradle":           "dependencies {\n    implementation 'com.google.guava:guava:32.1.2-jre'\n    testImplementation(\"org.junit.jupiter:junit-jupiter:5.9.0\")\n}\n",
	"crates/core/Cargo.toml":         "[package]\nname = \"core\"\n\n[dependencies]\nserde = \"1.0\"\ntokio = { version = \"1.35\", features = [\"full\"] }\n\n[dev-dependencies]\ncriterion = \"0.5\"\n",
	"crates/core/src/lib.rs":         "pub fn f() {}\n",
	"crates/core/tests/it.rs":        "#[test] fn t() {}\n",
	"py/pyproject.toml":              "[project]\nname = \"svc\"\ndependencies = [\n  \"requests>=2.31\",\n  \"pydantic==2.5.0; python_version >= '3.8'\",\n]\n",
	"py/requirements.txt":            "flask==3.0.0\npytest==8.0.0\n# comment\n",
	"Billing/Invoice.csproj":         `<Project><ItemGroup><PackageReference Include="Newtonsoft.Json" Version="13.0.3" /></ItemGroup></Project>`,
	"Billing/Billing.sln":            "Microsoft Visual Studio Solution File\n",
	"php/composer.json":              `{"require": {"monolog/monolog": "^3.5"}, "require-dev": {"phpunit/phpunit": "^10.5"}}`,
	"docs/README.md":                 "# Shop\n",
}

func writeTree(t *testing.T, root string, files map[string]string) {
	t.Helper()
	for rel, body := range files {
		p := filepath.Join(root, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
}

func manifestOf(t *testing.T, fp Fingerprint, rel string) Manifest {
	t.Helper()
	for _, m := range fp.Manifests {
		if m.Path == rel {
			return m
		}
	}
	t.Fatalf("manifest %s not found in %+v", rel, fp.Manifests)
	return Manifest{}
}

func hasDep(m Manifest, name, version string) bool {
	return slices.Contains(m.Dependencies, Dependency{Name: name, Version: version})
}

func TestDiscoverReadsManifestsWithoutRunningAnything(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root, polyglot)
	fp := Discover(context.Background(), root)

	if fp.Git || fp.Provenance != "filesystem walk" {
		t.Fatalf("plain folder: git=%v provenance=%q", fp.Git, fp.Provenance)
	}
	if !fp.Monorepo {
		t.Error("several manifest roots must be a monorepo")
	}
	if !hasDep(manifestOf(t, fp, "go.mod"), "github.com/stretchr/testify", "v1.9.0") {
		t.Error("direct go require missing")
	}
	if hasDep(manifestOf(t, fp, "go.mod"), "golang.org/x/exp", "v0.0.0-20240101") {
		t.Error("indirect go require must be skipped")
	}
	if !hasDep(manifestOf(t, fp, "web/package.json"), "express", "^4.18.2") || !hasDep(manifestOf(t, fp, "web/package.json"), "jest", "^29.7.0") {
		t.Errorf("npm dependencies and devDependencies: %+v", manifestOf(t, fp, "web/package.json"))
	}
	if !hasDep(manifestOf(t, fp, "pom.xml"), "org.junit.jupiter:junit-jupiter", "5.10.0") {
		t.Error("maven dependency missing")
	}
	if !hasDep(manifestOf(t, fp, "android/build.gradle"), "com.google.guava:guava", "32.1.2-jre") {
		t.Error("gradle dependency missing")
	}
	if !hasDep(manifestOf(t, fp, "crates/core/Cargo.toml"), "serde", "1.0") ||
		!hasDep(manifestOf(t, fp, "crates/core/Cargo.toml"), "tokio", "1.35") {
		t.Errorf("cargo dependencies: %+v", manifestOf(t, fp, "crates/core/Cargo.toml"))
	}
	if !hasDep(manifestOf(t, fp, "py/pyproject.toml"), "requests", ">=2.31") ||
		!hasDep(manifestOf(t, fp, "py/requirements.txt"), "flask", "==3.0.0") {
		t.Error("python dependencies missing")
	}
	if !hasDep(manifestOf(t, fp, "Billing/Invoice.csproj"), "Newtonsoft.Json", "13.0.3") {
		t.Error("nuget reference missing")
	}
	if !hasDep(manifestOf(t, fp, "php/composer.json"), "phpunit/phpunit", "^10.5") {
		t.Error("composer dev requirement missing")
	}

	if fp.Generated != 3 {
		t.Errorf("generated files = %d, want 3 (gen.pb.go, header marker, package-lock.json)", fp.Generated)
	}
	if !slices.Equal(fp.Tests.Dirs, []string{"tests"}) || fp.Tests.Colocated != 2 {
		t.Errorf("test layout: dirs=%v colocated=%d", fp.Tests.Dirs, fp.Tests.Colocated)
	}
	for _, fw := range []string{"go test", "jest", "junit", "pytest", "testify"} {
		if !slices.Contains(fp.Tests.Frameworks, fw) {
			t.Errorf("frameworks %v lack %q", fp.Tests.Frameworks, fw)
		}
	}
	for _, ep := range []string{"cmd/api", "cmd/worker", "src/"} {
		if !slices.Contains(fp.Entrypoints, ep) {
			t.Errorf("entrypoints %v lack %q", fp.Entrypoints, ep)
		}
	}
	support := map[string]string{}
	for _, l := range fp.Languages {
		support[l.Name] = l.Support
	}
	if support["go"] != "ast_treesitter" || support["rust"] != "ast_treesitter" || support["markdown"] != "text_rules" {
		t.Errorf("language support = %v", support)
	}
	if fp.Kinds["doc"] == 0 || fp.Kinds["config"] == 0 || fp.Kinds["code"] == 0 || fp.Kinds["test"] == 0 {
		t.Errorf("kind counts = %v", fp.Kinds)
	}
}

func TestDiscoverHashInvalidatesOnManifestChange(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root, polyglot)
	first := Discover(context.Background(), root)
	if again := Discover(context.Background(), root); again.Hash != first.Hash {
		t.Fatal("unchanged repository must keep its fingerprint hash")
	}
	writeTree(t, root, map[string]string{"go.mod": "module example.com/shop\n\ngo 1.24.0\n"})
	if changed := Discover(context.Background(), root); changed.Hash == first.Hash {
		t.Fatal("editing a manifest must change the fingerprint hash")
	}
}

func TestDiscoverIsFailOpenOnEmptyFolder(t *testing.T) {
	fp := Discover(context.Background(), t.TempDir())
	if fp.Files != 0 || fp.Hash == "" || fp.Monorepo || len(fp.Manifests) != 0 {
		t.Fatalf("empty folder fingerprint = %+v", fp)
	}
}

func TestDiscoverReadsGitHeadAndTrackedFiles(t *testing.T) {
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git not installed")
	}
	root := t.TempDir()
	writeTree(t, root, map[string]string{"go.mod": "module example.com/x\n\ngo 1.24.0\n"})
	run := func(args ...string) {
		t.Helper()
		cmd := exec.Command("git", append([]string{"-c", "user.name=t", "-c", "user.email=t@example.invalid"}, args...)...)
		cmd.Dir = root
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, out)
		}
	}
	run("init", "-q")
	run("add", "-A")
	run("commit", "-q", "-m", "init")

	fp := Discover(context.Background(), root)
	if !fp.Git || fp.Provenance != "git ls-files" || fp.Head == "" {
		t.Fatalf("git repository: git=%v provenance=%q head=%q", fp.Git, fp.Provenance, fp.Head)
	}
	if len(fp.Manifests) != 1 {
		t.Fatalf("manifests = %+v, want go.mod only", fp.Manifests)
	}
	run("commit", "-q", "--allow-empty", "-m", "second")
	if moved := Discover(context.Background(), root); moved.Hash == fp.Hash {
		t.Fatal("a new HEAD commit must change the fingerprint hash")
	}
}
